import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`financial-command-center`,heroTitle:`Build your financial command center in minutes`,heroSubtitle:`Perplexity Computer links your accounts, monitors your budget, and analyzes your investments — automatically.`,inputUrlCta:`Build my dashboard`,inputUrlPlaceholder:`Your current goal`,inputUrlPrefill:`Connect to my financial accounts via Plaid. Then build me a personal financial command center that includes: 1) A live budget monitor tracking income vs. spending across all accounts, 2) Investment portfolio analysis with allocation breakdown, performance vs. benchmarks, and risk metrics, 3) A financial health scorecard covering net worth trend, savings rate, debt-to-income ratio, and emergency fund status, 4) Monthly cash flow projections and spending category breakdowns, 5) Alerts for unusual transactions, budget overruns, and portfolio drift. My current goal is {url} - add anything else to help with this.`,heroOverlaySteps:[`Connecting to your financial accounts with read-only access via Plaid`,`Categorizing transactions and mapping your monthly cash flow`,`Analyzing portfolio allocation, performance, and risk exposure`,`Budget monitor, investment analysis, and health scorecard — ready to review`],generatingSteps:[`Visiting {url} to identify your accounts and establish secure read-only connections`,`Designing an agent to track budgets, categorize spending, and flag anomalies across all accounts`,`Configuring investment analysis with benchmark comparisons, allocation checks, and risk scoring`,`Setting up your live financial health dashboard with alerts and projections`],featureSectionTitle:`From linked accounts to total clarity`,featureCardTitles:[`Connects to your financial stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Plaid, Google Sheets, Notion, Gmail — Computer plugs into your tools so account data, alerts, and reports flow into one unified dashboard.`,`Monthly budget breakdowns. Portfolio risk reports. Net worth trend charts. Cash flow projections. Computer delivers financial intelligence formatted for quick decisions.`],capabilitySectionTitle:`Your financial analyst, on autopilot`,capabilitySectionSubtitle:`Link your accounts, step away, come back to a complete financial picture.`,capabilityCards:[{title:`Budget Monitoring`,description:`Computer can track every transaction across accounts — categorize spending, compare against budgets, and surface where your money actually goes.`},{title:`Investment Analysis`,description:`Computer can break down your portfolio by allocation, benchmark against indices, and flag concentration risk or underperforming positions.`},{title:`Health Scorecard`,description:`Computer can calculate your net worth trend, savings rate, debt-to-income ratio, and emergency fund coverage — updated as new data flows in.`},{title:`Connect Your Tools`,description:`Computer can read from Plaid, Google Sheets, Notion, and more — build workflows that centralize your entire financial picture.`},{title:`Remember & Learn`,description:`Computer can remember your income patterns, spending habits, and financial goals across sessions — so every analysis builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for unusual transactions, budget overruns, and portfolio drift — set up alerts that ping you when something needs attention.`}]});export{t as default};
